mapper.select:
SELECT COUNT(*)
  FROM sch01_info
 WHERE sch01_class_id = #{classId}

mapper.update:
UPDATE sch08_class
   SET sch08_class_nm = #{req.className},
       sch08_seq      = #{req.seq},
       sch08_use_yn   = #{req.useYn},
       sch08_note     = #{req.note}
 WHERE sch08_class_id = #{req.classId}
   AND sch08_person_id = #{personId}

mapper.delete:
